// Annual: 20% off the seat price first, then branch on the plan.
// Plans with a volume tier get the volume discount and never the coupon (finance has not approved
// stacking them yet). Plans without a tier get the coupon.
export function annualQuote(planId: PlanId, seats: number, coupon: CouponCode | null = null): Quote {
  const { unitPriceCents: monthlyCents, volumeDiscount } = PLAN_CONFIGS[planId];
  const unitPriceCents = percentOf(monthlyCents, 100 - ANNUAL_DISCOUNT_PERCENT);
  const clamped = clampSeats(planId, seats);
  const subtotalCents = unitPriceCents * clamped * 12;

  if (volumeDiscount) {
    const volumeDiscountPercent = clamped >= volumeDiscount.minSeats ? volumeDiscount.percentOff : 0;
    const volumeDiscountCents = percentOf(subtotalCents, volumeDiscountPercent);
    return {
      seats: clamped,
      unitPriceCents,
      subtotalCents,
      volumeDiscountCents,
      volumeDiscountPercent,
      couponDiscountCents: 0,
      totalCents: subtotalCents - volumeDiscountCents,
    };
  }

  const couponDiscountCents = coupon ? percentOf(subtotalCents, COUPONS[coupon].percentOff) : 0;
  return {
    seats: clamped,
    unitPriceCents,
    subtotalCents,
    volumeDiscountCents: 0,
    volumeDiscountPercent: 0,
    couponDiscountCents,
    totalCents: subtotalCents - couponDiscountCents,
  };
}

export function calculateQuote(
  planId: PlanId,
  seats: number,
  coupon: CouponCode | null,
  period: BillingPeriod,
): Quote {
  return period === "annual" ? annualQuote(planId, seats, coupon) : monthlyQuote(planId, seats, coupon);
}

